import{_ as t,o,c as s,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/c02b-pipeline-after-save.png",n="/rakkii-cars-guide/screenshots/v2/c02-new-inquiry.png",i="/rakkii-cars-guide/screenshots/v2/c03-parts-to-canvass.png",l="/rakkii-cars-guide/screenshots/v2/c04-commission.png",c="/rakkii-cars-guide/screenshots/v2/c08-monitoring.png",u="/rakkii-cars-guide/screenshots/v2/c05-insurance-calculator.png",f=JSON.parse('{"title":"Your day in sales","description":"","frontmatter":{},"headers":[],"relativePath":"sales/index.md","filePath":"sales/index.md","lastUpdated":1794643263000}'),d={name:"sales/index.md"};function p(h,e,g,m,y,k){return o(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="your-day-in-sales" tabindex="-1">Your day in sales <a class="header-anchor" href="#your-day-in-sales" aria-label="Permalink to &quot;Your day in sales&quot;">​</a></h1><p><strong>For:</strong> Sales agents · <strong>You use:</strong> the Sales hub and the Me hub</p><p>You bring customers in and follow them up until the car arrives. The desk turns your inquiry into a job and runs the repair. You earn commission on customers you referred, once the shop has been paid.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 Check follow-ups → 2 Log new inquiries → 3 Ask the desk to price parts</span></span>
<span class="line"><span>→ 4 Follow up → 5 Check your commission</span></span></code></pre></div><h2 id="_1-start-with-today-s-follow-ups" tabindex="-1">1. Start with today&#39;s follow-ups <a class="header-anchor" href="#_1-start-with-today-s-follow-ups" aria-label="Permalink to &quot;1. Start with today&#39;s follow-ups&quot;">​</a></h2><ol><li>Open the app. You land on <strong>My pipeline</strong>.</li><li>Press <strong>Follow-up due</strong> to see who to contact today. The status chips (<strong>All open</strong>, <strong>For canvass</strong>, <strong>Booked</strong>, <strong>Quoted</strong>, <strong>Waiting for LOA</strong>) narrow the list.</li><li>Call or message those customers first.</li></ol><p><img src="`+a+'" alt="My pipeline with one inquiry"></p><h2 id="_2-log-a-new-inquiry" tabindex="-1">2. Log a new inquiry <a class="header-anchor" href="#_2-log-a-new-inquiry" aria-label="Permalink to &quot;2. Log a new inquiry&quot;">​</a></h2><p>Do this for every customer who calls, messages or walks up to you. Don&#39;t use <strong>New job</strong>; that&#39;s for the desk.</p><ol><li>Press <strong>New inquiry</strong>.</li><li>Fill in <strong>Customer name</strong>, <strong>Mobile</strong> and <strong>Plate</strong>. Add the car&#39;s year, make and model if you know them.</li><li>In <strong>What do they want?</strong>, write the request in plain words, for example &quot;Rear bumper dent, wants an insurance claim with Malayan.&quot;</li><li>Set <strong>Next follow-up</strong>.</li><li>Press <strong>Add inquiry</strong>. You&#39;ll see &quot;Inquiry added.&quot;</li></ol><p><img src="'+n+'" alt="New inquiry dialog"></p><p>The inquiry becomes a job at <strong>New inquiry</strong>, with you as the sales advisor. The desk confirms the booking and quotes it.</p><h2 id="_3-ask-the-desk-to-price-parts" tabindex="-1">3. Ask the desk to price parts <a class="header-anchor" href="#_3-ask-the-desk-to-price-parts" aria-label="Permalink to &quot;3. Ask the desk to price parts&quot;">​</a></h2><p>If the customer needs parts, ask for supplier prices from the job itself:</p><ol><li>In your pipeline, press the job number (for example <code>JOB-20261114-1142</code>) to open the job.</li><li>On <strong>Overview</strong>, find <strong>Parts to canvass</strong>.</li><li>Enter each <strong>Part name</strong> and <strong>Qty</strong>, press <strong>Add part</strong>, then <strong>Send for canvass</strong>.</li><li>Once the canvass is approved, enter the <strong>Sell ₱ (each)</strong> price and press <strong>Save price</strong>.</li></ol><p><img src="'+i+'" alt="Parts to canvass card"></p><p>You can view the job&#39;s status and print the estimate, but you can&#39;t change its status, work lines or payments.</p><h2 id="_4-follow-up" tabindex="-1">4. Follow up <a class="header-anchor" href="#_4-follow-up" aria-label="Permalink to &quot;4. Follow up&quot;">​</a></h2><p>On each pipeline row:</p><ul><li><strong>Set follow-up</strong>: pick the next date and add a note.</li><li><strong>Print estimate</strong>: the customer&#39;s estimate (sell prices only).</li><li><strong>Mark lost</strong>: the customer said no. Give a reason. This only works on <strong>New inquiry</strong> rows.</li></ul><div class="tip custom-block"><p class="custom-block-title">Daily habit</p><p>Clear <strong>Overdue</strong> every morning before taking new inquiries.</p></div><h2 id="_5-check-your-commission" tabindex="-1">5. Check your commission <a class="header-anchor" href="#_5-check-your-commission" aria-label="Permalink to &quot;5. Check your commission&quot;">​</a></h2><p>Open <strong>My commission</strong>. Each line moves through <strong>Accruing → Due → Approved → Paid</strong>.</p><p><img src="'+l+'" alt="My commission"></p><p>How it works with the shop&#39;s default settings:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Default</th></tr></thead><tbody><tr><td>Who earns</td><td>The person set as <strong>Referred by (staff)</strong> on the job. The desk sets this.</td></tr><tr><td>Which job</td><td>The customer&#39;s first referred job. Repeat visits don&#39;t earn again.</td></tr><tr><td>Rate</td><td>5% of what the customer actually paid</td></tr><tr><td>Minimum</td><td>No commission if the customer paid less than ₱30,000</td></tr><tr><td>When</td><td>30 days after release, or after the customer finishes paying if later</td></tr></tbody></table><p><strong>Example:</strong> your new customer&#39;s job is released on March 1 and they paid ₱48,000. You earn 5% × ₱48,000 = <strong>₱2,400</strong>, due March 31.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t see a line?</p><p>Only the owner or admin can set <strong>Referred by (staff)</strong>. If you referred a customer and see no line, tell the owner.</p></div><h2 id="more-sales-tools" tabindex="-1">More sales tools <a class="header-anchor" href="#more-sales-tools" aria-label="Permalink to &quot;More sales tools&quot;">​</a></h2><h3 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h3><p><strong>Monitoring</strong> shows your monthly <strong>Quota</strong>, <strong>Actual</strong> and <strong>Surplus / deficit</strong>. Insurance jobs count the LOA amount in the LOA&#39;s month. Other jobs count the approved PO or quote.</p><p><img src="'+c+'" alt="Sales monitoring"></p><h3 id="insurance-premium-calculator" tabindex="-1">Insurance premium calculator <a class="header-anchor" href="#insurance-premium-calculator" aria-label="Permalink to &quot;Insurance premium calculator&quot;">​</a></h3><p><strong>Insurance</strong> gives a customer a quick premium estimate. It&#39;s not a policy.</p><ol><li>Pick the vehicle type, then <strong>TPL</strong> or <strong>Comprehensive</strong>, and any add-ons.</li><li>Read the estimate.</li><li>Save it against a pipeline inquiry or a customer name and plate.</li></ol><p><img src="'+u+'" alt="Insurance calculator"></p><h3 id="quarterly-incentive" tabindex="-1">Quarterly incentive <a class="header-anchor" href="#quarterly-incentive" aria-label="Permalink to &quot;Quarterly incentive&quot;">​</a></h3><p><strong>Me › My incentive</strong> shows your quarterly unit target and progress. The owner records the bonus; it&#39;s added to payroll.</p><h3 id="your-clock-leave-and-payslip" tabindex="-1">Your clock, leave and payslip <a class="header-anchor" href="#your-clock-leave-and-payslip" aria-label="Permalink to &quot;Your clock, leave and payslip&quot;">​</a></h3><p>See <a href="/rakkii-cars-guide/me/">Me hub</a>.</p>',40)])])}const w=t(d,[["render",p]]);export{f as __pageData,w as default};
